const schema = [{"@context":"https://schema.org","@type":"Service","name":"Manuscript Formatting Service","serviceType":"Journal manuscript formatting and reference styling","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/publication-support/journal-manuscript-formatting-services/","description":"Formatting to your journal's instructions for authors: Vancouver, APA, AMA, Harvard and IEEE styles, figures, tables and submission-ready files.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What are the formatting requirements for a journal manuscript?","acceptedAnswer":{"@type":"Answer","text":"They differ by journal, which is the whole difficulty. Expect rules on section order and heading names, word limits and what counts toward them, abstract type and length, keyword count, reference style and cap, figure resolution and file format, table layout, and where each declaration sits. The journal's instructions for authors is the only authority; anything else is a guess."}},{"@type":"Question","name":"What is the difference between Vancouver, APA and Harvard?","acceptedAnswer":{"@type":"Answer","text":"Vancouver is numbered: citations appear as [7] and the list is ordered by first appearance. APA and Harvard are both author–date, so citations read (Halvorsen et al., 2022) and the list is alphabetical — but they punctuate, italicise and abbreviate differently, and APA uses \"&\" where Harvard uses \"and\". Medicine mostly uses Vancouver or AMA; psychology and the social sciences mostly APA. The switcher above shows the same reference in all three."}},{"@type":"Question","name":"Which reference styles do you handle?","acceptedAnswer":{"@type":"Answer","text":"Vancouver, APA 7th, Harvard, AMA, Chicago in both forms, MLA and IEEE, plus any journal house style supplied in the instructions for authors. House styles are common at society journals and are usually a variant of one of the above with three or four specific departures."}},{"@type":"Question","name":"What file formats do journals want?","acceptedAnswer":{"@type":"Answer","text":"Almost all take DOCX for the manuscript. Beyond that it splits: some want figures embedded at first mention, others want them as separate TIFF or EPS files uploaded individually; some want tables in the manuscript, others as a separate file. Supplementary material usually has its own naming convention. We deliver DOCX and PDF, with figures packaged the way your journal asks."}},{"@type":"Question","name":"What resolution do figures need to be?","acceptedAnswer":{"@type":"Answer","text":"Typically 300 dpi for photographs and halftones, and 600 dpi or higher for line art and graphs, at the final printed width. A figure pasted in from a screen is around 96 dpi and will usually be rejected at upload — the portal checks before a human does. Where a figure is too low, we rebuild it from your source data rather than upscaling it, because upscaling does not add detail."}},{"@type":"Question","name":"How should tables and figures be laid out?","acceptedAnswer":{"@type":"Answer","text":"Numbered consecutively in order of first mention, each with a caption that makes sense on its own, each called out in the text. Convention puts table captions above and figure captions below. Footnote symbols follow a sequence the journal specifies, units are consistent throughout, and any reproduced material carries a permission line."}},{"@type":"Question","name":"Why do journals return manuscripts for formatting?","acceptedAnswer":{"@type":"Answer","text":"Because it can be checked in two minutes without reading the science, so it is checked first. The common causes are the wrong reference style, citations that do not match the list, over the word limit, figures below resolution, missing declarations, and a heading the template does not use. None of it reflects on the work, and all of it costs you a cycle."}},{"@type":"Question","name":"My paper was rejected. Do I have to reformat for the next journal?","acceptedAnswer":{"@type":"Answer","text":"Usually yes, and more than authors expect. A different journal often means a different reference style, a different abstract structure, different heading names and a different figure specification. Some journals now accept format-free first submissions and only require formatting on acceptance — worth checking, because it saves the work entirely if you are rejected."}},{"@type":"Question","name":"Will you cut my manuscript to fit the word limit?","acceptedAnswer":{"@type":"Answer","text":"Only with tracked changes, so you see and can reverse every cut. We reduce by tightening rather than deleting content, and we tell you where the remaining excess sits if the limit still cannot be met without a decision only you can make. Note that journals count differently — some include references and the abstract, most do not."}},{"@type":"Question","name":"Do you format theses as well as journal articles?","acceptedAnswer":{"@type":"Answer","text":"Yes, and they are different jobs. A thesis follows your university's own specification, which is usually stricter about margins, pagination and front matter than any journal. Converting a thesis chapter into a journal article is different again — it needs restructuring and cutting, not just restyling, and we will say so rather than format a chapter and call it a paper."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Publication support","item":"https://pubrica.com/services/publication-support/"},{"@type":"ListItem","position":3,"name":"Manuscript formatting","item":"https://pubrica.com/services/publication-support/journal-manuscript-formatting-services/"}]}];

